class Solution {
public:
    vector<int> finalPrices(vector<int>& prices) {
        int n = prices.size();
        vector<int> answer(n);
        vector<int> stk;
        stk.reserve(n);
        for (int i = n - 1; i >= 0; --i) {
            while (!stk.empty() && prices[stk.back()] > prices[i]) {
                stk.pop_back();
            }
            answer[i] = prices[i] - (stk.empty() ? 0 : prices[stk.back()]);
            stk.push_back(i);
        }
        return answer;
    }
};
